#!/usr/bin/env bash
# Regenerates third-party/boost/ -- the minimal set of Boost headers vcache
# actually includes.
#
# Boost ships 15,828 headers; vcache opens 932 of them, essentially all pulled in
# by Spirit X3 through Fusion, MPL and Preprocessor. Carrying the full 104 MB
# tree to use 4 MB of it is not worth it, so the subset is committed to the
# repository and this script rebuilds it.
#
# Method: compile every translation unit with -H, which lists every header the
# compiler actually opens, and keep exactly those. The result is then verified by
# recompiling everything against the subset alone, so an incomplete subset fails
# here rather than at someone else's build.
#
# Run this when:
#   - a new #include reaches a part of Boost the subset does not carry, and the
#     build fails on a missing boost/... header;
#   - you bump BOOST_VERSION;
#   - you want the subset to cover an additional compiler. Pass them all
#     (`./regen-boost-subset.sh g++ clang++`) and the union is written out, since
#     Boost selects different config headers per compiler.
#
# Usage:  ./regen-boost-subset.sh [CXX...]        (default: g++)

set -euo pipefail

TP="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
TOP="$(dirname "$TP")"
DL="$TP/.dl"

BOOST_VERSION="1.86.0"
BOOST_UNDERSCORE="boost_1_86_0"
BOOST_URL="https://archives.boost.io/release/${BOOST_VERSION}/source/${BOOST_UNDERSCORE}.tar.gz"
BOOST_SHA256="2575e74ffc3ef1cd0babac2c1ee8bdb5782a0ee672b1912da40e5b4b591ca01f"

FULL="$TP/boost-full-${BOOST_VERSION}"   # gitignored scratch tree
OUT="$TP/boost"                          # committed subset
MANIFEST="$OUT/SUBSET-FILES.txt"

COMPILERS=("$@")
[[ ${#COMPILERS[@]} -eq 0 ]] && COMPILERS=(g++)

log() { printf '>> %s\n' "$*"; }

# ---- get a full Boost tree to select from -----------------------------------

if [[ ! -d "$FULL/boost" ]]; then
  mkdir -p "$DL"
  if [[ ! -f "$DL/boost.tar.gz" ]]; then
    log "downloading Boost ${BOOST_VERSION} (149 MB, one time)"
    curl -sSL --fail -o "$DL/boost.tar.gz" "$BOOST_URL"
  fi
  actual="$(sha256sum "$DL/boost.tar.gz" | cut -d' ' -f1)"
  if [[ "$actual" != "$BOOST_SHA256" ]]; then
    echo "checksum mismatch for boost.tar.gz" >&2
    echo "  expected $BOOST_SHA256" >&2
    echo "  actual   $actual" >&2
    exit 1
  fi
  log "extracting full Boost headers to $FULL"
  rm -rf "$FULL"; mkdir -p "$FULL"
  tar xzf "$DL/boost.tar.gz" -C "$DL" "${BOOST_UNDERSCORE}/boost"
  mv "$DL/${BOOST_UNDERSCORE}/boost" "$FULL/boost"
  rmdir "$DL/${BOOST_UNDERSCORE}"
fi

# ---- ask each compiler which Boost headers it reads -------------------------

WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

for cxx in "${COMPILERS[@]}"; do
  if ! command -v "$cxx" >/dev/null 2>&1; then
    log "skipping $cxx (not installed)"
    continue
  fi
  log "collecting includes with $cxx"
  for f in $(find "$TOP/src" "$TOP/tests" -name '*.cc'); do
    # -H, not -MM. Boost marks several headers with `#pragma GCC system_header`
    # (boost/config/detail/suffix.hpp among them), and -MM omits system headers
    # *and everything they include* -- which silently drops real dependencies
    # such as boost/config/helper_macros.hpp. -H reports every header actually
    # opened, regardless of that marking, so the result is exact rather than an
    # under-approximation that only fails at build time.
    "$cxx" -std=c++20 -O3 \
      -I"$TOP/src" -I"$FULL" -I"$TP/tomlplusplus" -I"$TP/blake3" \
      $(pkg-config --cflags libcurl 2>/dev/null) \
      -DTOML_EXCEPTIONS=0 -H -fsyntax-only "$f" 2>>"$WORK/headers.txt" || true
  done
done

grep -oE "$FULL/boost/[^ ]*" "$WORK/headers.txt" 2>/dev/null \
  | sed "s|^$FULL/||" \
  | sort -u > "$WORK/used.txt"

count="$(wc -l < "$WORK/used.txt")"
if [[ "$count" -lt 100 ]]; then
  echo "only $count Boost headers detected -- something went wrong; refusing to write" >&2
  exit 1
fi
log "$count headers opened across all translation units"


# ---- write the subset -------------------------------------------------------

log "writing $count headers to $OUT"
rm -rf "$OUT"; mkdir -p "$OUT"
(cd "$FULL" && tar cf - -T "$WORK/used.txt") | (cd "$OUT" && tar xf -)

{
  echo "# Boost ${BOOST_VERSION} -- minimal subset used by vcache."
  echo "# Generated by third-party/regen-boost-subset.sh; do not edit by hand."
  echo "# Compilers sampled: ${COMPILERS[*]}"
  echo "# $count of $(find "$FULL/boost" -type f | wc -l) headers."
  cat "$WORK/used.txt"
} > "$MANIFEST"

cat > "$OUT/README.md" <<EOF
# Boost ${BOOST_VERSION}, minimal subset

$count of $(find "$FULL/boost" -type f | wc -l) headers, $(du -sh "$OUT/boost" | cut -f1) instead of
$(du -sh "$FULL/boost" | cut -f1). Only Boost.Spirit X3 is used directly; the rest is what
X3 pulls in through Fusion, MPL and Preprocessor.

Regenerate with \`third-party/regen-boost-subset.sh\` (or \`make boost-subset\`)
after adding an include that reaches a new part of Boost. \`SUBSET-FILES.txt\`
lists the exact contents.

Boost is distributed under the Boost Software License 1.0; see LICENSE.
EOF

# Keep the licence alongside the code it covers.
if [[ -f "$DL/${BOOST_UNDERSCORE}/LICENSE_1_0.txt" ]]; then
  cp "$DL/${BOOST_UNDERSCORE}/LICENSE_1_0.txt" "$OUT/LICENSE"
else
  tar xzOf "$DL/boost.tar.gz" "${BOOST_UNDERSCORE}/LICENSE_1_0.txt" > "$OUT/LICENSE" 2>/dev/null || true
fi

log "subset is $(du -sh --apparent-size "$OUT" | cut -f1) across $(find "$OUT/boost" -type f | wc -l) headers"

# Prove the result actually builds before leaving it in place: a silently
# incomplete subset is the failure mode worth guarding against.
log "verifying every translation unit compiles against the subset"
failed=0
for f in $(find "$TOP/src" "$TOP/tests" -name '*.cc'); do
  if ! "${COMPILERS[0]}" -std=c++20 -O3 \
       -I"$TOP/src" -I"$OUT" -I"$TP/tomlplusplus" -I"$TP/blake3" \
       $(pkg-config --cflags libcurl 2>/dev/null) \
       -DTOML_EXCEPTIONS=0 -fsyntax-only "$f" 2>"$WORK/err.txt"; then
    echo "FAILED: $f" >&2
    head -5 "$WORK/err.txt" >&2
    failed=1
  fi
done
if [[ $failed -ne 0 ]]; then
  echo "subset is incomplete -- not usable" >&2
  exit 1
fi

log "verified; done -- rebuild and run the tests"
